using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, double> _prices = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _productsByCategory = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, double price)
    {
        _categories[code] = category;
        _prices[code] = price;

        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(_productsByCategory, category, out bool exists);
        if (!exists)
            list = new List<string>();
        list!.Add(code);
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    /// <summary>
    /// Computes the total price for a batch of product codes.
    /// Uses SIMD-accelerated vectorized summation over the collected prices.
    /// </summary>
    public double GetTotalPrice(IReadOnlyList<string> codes)
    {
        int count = codes.Count;
        if (count == 0)
            return 0d;

        // Collect matching prices into a contiguous buffer for vectorized summation
        double[] buffer = new double[count];
        int found = 0;
        for (int i = 0; i < count; i++)
        {
            if (_prices.TryGetValue(codes[i], out var price))
                buffer[found++] = price;
        }

        return SumVectorized(buffer.AsSpan(0, found));
    }

    /// <summary>
    /// Overload accepting any enumerable for backward compatibility.
    /// </summary>
    public double GetTotalPrice(IEnumerable<string> codes)
    {
        if (codes is IReadOnlyList<string> list)
            return GetTotalPrice(list);

        double total = 0d;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        if (_productsByCategory.TryGetValue(category, out var products))
            return new List<string>(products);
        return new List<string>();
    }

    /// <summary>
    /// SIMD-accelerated summation using hardware vectors.
    /// Processes Vector&lt;double&gt;.Count elements per iteration (e.g., 4 on AVX2).
    /// </summary>
    private static double SumVectorized(ReadOnlySpan<double> values)
    {
        int vectorSize = Vector<double>.Count;
        int i = 0;

        if (values.Length >= vectorSize)
        {
            var accumulator = Vector<double>.Zero;
            int limit = values.Length - (values.Length % vectorSize);

            for (; i < limit; i += vectorSize)
            {
                var vec = new Vector<double>(values.Slice(i, vectorSize));
                accumulator += vec;
            }

            double total = Vector.Sum(accumulator);
            // Handle remaining elements
            for (; i < values.Length; i++)
                total += values[i];
            return total;
        }

        // Scalar fallback for small spans
        double sum = 0d;
        for (; i < values.Length; i++)
            sum += values[i];
        return sum;
    }
}

